        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos I.19</em> <small>(c. 350 AD)</small><p>&#x27;But of him are ye in Christ Jesus, who of God is made unto us wisdom, and righteousness, and sanctification, and redemption&#x27; — Athanasius marks the four-fold sophia + dikaiosynē + hagiasmos + apolytrōsis attribute-cluster as the FULL Christological-soteriology in Pauline-shorthand. Christ IS each-of-these (predicate-identity, not mere-instrumentality). The four-fold corresponds to the four-fold problem-of-Adam: ignorance (→ Christ-wisdom), unrighteousness (→ Christ-righteousness), pollution (→ Christ-sanctification), captivity (→ Christ-redemption). Tewahedo soteriological-preaching cites 1 Cor 1:30 as the comprehensive Christological-attribute-list.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
