    (
        8,
        6,
        "g",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos III.6</em> <small>(c. 350 AD)</small><p>&#x27;But to us there is but one God, the Father, of whom are all things, and we in him; and one Lord Jesus Christ, by whom are all things, and we by him&#x27; — Athanasius marks the Pauline-binitarian-formula (heis theos ho patēr / heis kyrios Iēsous Christos) as the structural-blueprint of the Nicene-Creed. The heis theos is appositively-identified with ho patēr (the Father); the heis kyrios is appositively-identified with Iēsous Christos. The two-clauses do NOT establish two-gods but distribute the Shema&#x27;s-heis (cf. Deut 6:4 LXX kyrios ho theos hēmōn kyrios heis estin) across the Father-as-heis-theos and the Son-as-heis-kyrios. The &#x27;di&#x27; hou&#x27; (through-whom) phrase reserves to the Son the same creator-prerogative as the Father, marking the Son&#x27;s divinity. Tewahedo Trisagion-theology preserves the Pauline binitarian-distribution at every Anaphora.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
    ),
