    (
        15,
        45,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos II.65</em> <small>(c. 350 AD)</small><p>&#x27;And so it is written, The first man Adam was made a living soul; the last Adam was made a quickening spirit&#x27; — Athanasius marks ho eschatos Adam eis pneuma zōopoioun (the last Adam unto a life-giving spirit) as the FULL Adam-Christ-typological-completion. The first Adam was made-a-living-soul (received life from outside); the last Adam IS-a-life-giving-Spirit (gives life from himself). The asymmetry is Christ&#x27;s-divinity emerging through the Pauline-typological-structure: Christ is not merely-the-better-Adam but the life-giving-Word-incarnate. Tewahedo Pentecost (Päraqlitos) liturgy cites 1 Cor 15:45 + Jn 20:22 (Jesus breathes Spirit on disciples) as the Pneuma-zōopoioun life-giving-Spirit pair.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
    ),
